<?php
declare(strict_types=1);
if(!defined('CMS_ENTRY'))exit;
function base32_encode(string $raw):string{$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$out='';$buffer=0;$bits=0;foreach(unpack('C*',$raw) as $byte){$buffer=($buffer<<8)|$byte;$bits+=8;while($bits>=5){$bits-=5;$out.=$alphabet[($buffer>>$bits)&31];}$buffer&=(1<<$bits)-1;}if($bits)$out.=$alphabet[($buffer<<(5-$bits))&31];return $out;}
function base32_decode(string $value):string{$value=strtoupper(str_replace(' ','',$value));if(!preg_match('/^[A-Z2-7]{16,128}$/D',$value))fail(400,'Invalid authenticator key.');$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$buffer=0;$bits=0;$out='';foreach(str_split($value) as $char){$buffer=($buffer<<5)|strpos($alphabet,$char);$bits+=5;if($bits>=8){$bits-=8;$out.=chr(($buffer>>$bits)&255);}$buffer&=(1<<$bits)-1;}return $out;}
function totp_at(string $secret,int $timestamp,int $digits=6):string{$step=intdiv($timestamp,30);$counter=pack('N2',intdiv($step,4294967296),$step%4294967296);$hash=hash_hmac('sha1',$counter,base32_decode($secret),true);$offset=ord($hash[19])&15;$code=unpack('N',substr($hash,$offset,4))[1]&0x7fffffff;return str_pad((string)($code%(10**$digits)),$digits,'0',STR_PAD_LEFT);}
function mfa_key():string{$path=private_dir().'/mfa.key';if(is_file($path)){$key=file_get_contents($path);if(strlen($key)!==32)fail(503,'Authenticator encryption key is invalid. Restore a matching full backup.');return $key;}$key=random_bytes(32);atomic_write($path,$key);return $key;}
function seal_secret(string $secret):string{$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($secret,'aes-256-gcm',mfa_key(),OPENSSL_RAW_DATA,$iv,$tag,'1ded-php-mfa-v1');if($cipher===false)fail(500,'Authenticator encryption failed.');return base64_encode($iv.$tag.$cipher);}
function open_secret(string $box,?string $key=null):string{$data=base64_decode($box,true);if($data===false||strlen($data)<29)fail(503,'Authenticator configuration is invalid.');$secret=openssl_decrypt(substr($data,28),'aes-256-gcm',$key??mfa_key(),OPENSSL_RAW_DATA,substr($data,0,12),substr($data,12,16),'1ded-php-mfa-v1');if($secret===false)fail(503,'Authenticator key cannot be opened. Restore a matching full backup.');return $secret;}
function security_data(Store $s,string $id):array{return $s->get('security',[])[$id]??[];}
function save_security(Store $s,string $id,array $value):void{$all=$s->get('security',[]);if($value)$all[$id]=$value;else unset($all[$id]);$s->set('security',$all);}
function mfa_enabled(Store $s,string $id):bool{return !empty(security_data($s,$id)['enabled']);}
function current_password(Store $s,array $u,mixed $password):void{limited($s,'reauth',10,900);$user=$s->query('SELECT hash FROM cms_users WHERE id=?',[$u['user_id']])->fetch();if(!is_string($password)||strlen($password)>256||!$user||!password_verify($password,$user['hash']))fail(403,'Current password is incorrect.');}
function security_limit(Store $s,string $identity,int $limit=10,int $duration=900):void{$id=hash('sha256','security:'.$identity);$now=time();$s->query('DELETE FROM cms_rates WHERE expires<?',[$now]);$r=$s->query('SELECT * FROM cms_rates WHERE id=?',[$id])->fetch();if($r){if((int)$r['hits']>=$limit)fail(429,'Too many authentication attempts. Try again later.');$s->query('UPDATE cms_rates SET hits=hits+1 WHERE id=?',[$id]);}else $s->query('INSERT INTO cms_rates VALUES (?,?,?)',[$id,1,$now+$duration]);}
function match_totp(string $secret,string $code,int $last):?int{$code=preg_replace('/\s+/','',$code);if(!preg_match('/^\d{6}$/D',$code))return null;$step=intdiv(time(),30);foreach([0,-1,1] as $delta){$n=$step+$delta;if($n>$last&&hash_equals(totp_at($secret,$n*30),$code))return $n;}return null;}
function factor_verify(Store $s,string $id,mixed $code,bool $allowBackup=true):bool{$d=security_data($s,$id);if(empty($d['enabled']))return true;if(!is_string($code))return false;$code=trim($code);$step=match_totp(open_secret($d['secret']),$code,(int)($d['lastStep']??-1));if($step!==null){$d['lastStep']=$step;save_security($s,$id,$d);return true;}if($allowBackup){$normalized=strtolower(preg_replace('/[\s-]+/','',$code));if(preg_match('/^[a-f0-9]{32}$/D',$normalized))foreach($d['backupHashes']??[] as $i=>$hash)if(hash_equals($hash,hash('sha256',$normalized))){array_splice($d['backupHashes'],$i,1);save_security($s,$id,$d);$s->audit($id,'Used a single-use MFA recovery code');return true;}}return false;}
function step_up(Store $s,array $u,mixed $factor):void{if(mfa_enabled($s,$u['user_id'])){security_limit($s,'factor:'.$u['user_id']);if(!factor_verify($s,$u['user_id'],$factor))fail(403,'Enter a fresh authenticator code or unused MFA recovery code. Codes cannot be reused.');}}
function backup_codes():array{$plain=[];$hashes=[];for($i=0;$i<10;$i++){$code=bin2hex(random_bytes(16));$plain[]=implode('-',str_split($code,8));$hashes[]=hash('sha256',$code);}return ['codes'=>$plain,'hashes'=>$hashes];}
function clear_challenges(Store $s,string $id):void{$all=$s->get('loginChallenges',[]);foreach($all as $key=>$value)if($value['user']===$id)unset($all[$key]);$s->set('loginChallenges',$all);}
function establish_session(Store $s,array $user):void{$old=$_COOKIE['cms_php_session']??'';if(is_string($old)&&preg_match('/^[a-f0-9]{64}$/D',$old))$s->query('DELETE FROM cms_sessions WHERE hash=?',[hash('sha256',$old)]);$raw=bin2hex(random_bytes(32));$csrf=bin2hex(random_bytes(32));$s->query('DELETE FROM cms_sessions WHERE expires<?',[time()]);$rows=$s->query('SELECT hash FROM cms_sessions WHERE user_id=? ORDER BY expires DESC',[$user['id']])->fetchAll();foreach(array_slice($rows,9) as $row)$s->query('DELETE FROM cms_sessions WHERE hash=?',[$row['hash']]);$s->query('INSERT INTO cms_sessions VALUES (?,?,?,?)',[hash('sha256',$raw),$user['id'],$csrf,time()+28800]);session_cookie($raw,28800);$s->audit($user['email'],'Signed in'.(mfa_enabled($s,$user['id'])?' with two-factor authentication':''));}
function start_login_challenge(Store $s,array $user):array{$all=$s->get('loginChallenges',[]);foreach($all as $key=>$c)if($c['expires']<time()||$c['user']===$user['id'])unset($all[$key]);if(count($all)>=100)fail(429,'Too many pending logins. Try later.');$raw=bin2hex(random_bytes(32));$all[hash('sha256',$raw)]=['user'=>$user['id'],'expires'=>time()+300,'attempts'=>0,'binding'=>hash('sha256',($_SERVER['REMOTE_ADDR']??'')."\n".($_SERVER['HTTP_USER_AGENT']??''))];$s->set('loginChallenges',$all);$old=$_COOKIE['cms_php_session']??'';if(is_string($old))$s->query('DELETE FROM cms_sessions WHERE hash=?',[hash('sha256',$old)]);session_cookie('',0);return ['mfaRequired'=>true,'challenge'=>$raw,'expiresIn'=>300];}
function security_public(Store $s,array $u):array{$d=security_data($s,$u['user_id']);return ['enabled'=>!empty($d['enabled']),'recoveryCodesRemaining'=>count($d['backupHashes']??[]),'pending'=>!empty($d['pending'])&&($d['pending']['expires']??0)>time()];}
function security_routes(Store $s,string $path,string $method):bool{
 if($path==='/api/login/mfa'&&$method==='POST'){limited($s,'mfa-login',15,900);$b=input_json();$raw=txt($b['challenge']??'',64);$key=hash('sha256',$raw);$all=$s->get('loginChallenges',[]);$c=$all[$key]??null;if(!$c||$c['expires']<time()||$c['attempts']>=5||!hash_equals($c['binding'],hash('sha256',($_SERVER['REMOTE_ADDR']??'')."\n".($_SERVER['HTTP_USER_AGENT']??''))))fail(401,'Login challenge expired. Sign in again.');$user=$s->query('SELECT * FROM cms_users WHERE id=?',[$c['user']])->fetch();if(!$user||!mfa_enabled($s,$user['id']))fail(401,'Sign in again.');security_limit($s,'login:'.$user['id']);$all[$key]['attempts']++;$s->set('loginChallenges',$all);if(!factor_verify($s,$user['id'],$b['code']??''))fail(401,'Code is incorrect, expired or already used.');unset($all[$key]);$s->set('loginChallenges',$all);establish_session($s,$user);json_response(['ok'=>true]);}
 if(!str_starts_with($path,'/api/security')&&!str_starts_with($path,'/api/sessions'))return false;
 $u=auth($s);$id=$u['user_id'];
 if($path==='/api/security'&&$method==='GET')json_response(security_public($s,$u));
 if($path==='/api/security/mfa/begin'&&$method==='POST'){$b=input_json();current_password($s,$u,$b['current']??'');if(mfa_enabled($s,$id))fail(409,'Two-factor authentication is already enabled.');$secret=base32_encode(random_bytes(20));$nonce=bin2hex(random_bytes(16));$d=security_data($s,$id);$d['pending']=['secret'=>seal_secret($secret),'nonce'=>hash('sha256',$nonce),'session'=>$u['hash'],'expires'=>time()+600];save_security($s,$id,$d);json_response(['secret'=>$secret,'enrollment'=>$nonce,'issuer'=>'1DED Free CMS','account'=>$u['email'],'digits'=>6,'period'=>30,'algorithm'=>'SHA1']);}
 if($path==='/api/security/mfa/confirm'&&$method==='POST'){$b=input_json();security_limit($s,'enroll:'.$id);$d=security_data($s,$id);$p=$d['pending']??null;if(!$p||$p['expires']<time()||!hash_equals($p['session'],$u['hash'])||!hash_equals($p['nonce'],hash('sha256',txt($b['enrollment']??'',100))))fail(409,'Enrollment expired. Start again.');$step=match_totp(open_secret($p['secret']),txt($b['code']??'',20),-1);if($step===null)fail(400,'Authenticator code is incorrect. Check your phone’s time.');$codes=backup_codes();save_security($s,$id,['enabled'=>true,'secret'=>$p['secret'],'lastStep'=>$step,'backupHashes'=>$codes['hashes']]);$s->query('DELETE FROM cms_sessions WHERE user_id=? AND hash<>?',[$id,$u['hash']]);clear_challenges($s,$id);$s->audit($u['email'],'Enabled two-factor authentication; revoked other sessions');json_response(['ok'=>true,'codes'=>$codes['codes']]);}
 if(in_array($path,['/api/security/mfa/disable','/api/security/mfa/codes'],true)&&$method==='POST'){$b=input_json();current_password($s,$u,$b['current']??'');if(!mfa_enabled($s,$id))fail(409,'Two-factor authentication is not enabled.');step_up($s,$u,$b['factor']??'');if($path==='/api/security/mfa/disable'){save_security($s,$id,[]);clear_challenges($s,$id);$s->query('DELETE FROM cms_sessions WHERE user_id=? AND hash<>?',[$id,$u['hash']]);$s->audit($u['email'],'Disabled two-factor authentication; revoked other sessions');json_response(['ok'=>true]);}$codes=backup_codes();$d=security_data($s,$id);$d['backupHashes']=$codes['hashes'];save_security($s,$id,$d);$s->audit($u['email'],'Replaced MFA recovery codes');json_response(['ok'=>true,'codes'=>$codes['codes']]);}
 if($path==='/api/sessions'&&$method==='GET'){$rows=$s->query('SELECT hash,expires FROM cms_sessions WHERE user_id=? AND expires>? ORDER BY expires DESC',[$id,time()])->fetchAll();json_response(array_map(fn($r)=>['id'=>hash('sha256','session-list:'.$r['hash']),'current'=>hash_equals($r['hash'],$u['hash']),'expires'=>gmdate('c',(int)$r['expires'])],$rows));}
 if($path==='/api/sessions/revoke-others'&&$method==='POST'){$s->query('DELETE FROM cms_sessions WHERE user_id=? AND hash<>?',[$id,$u['hash']]);$s->audit($u['email'],'Signed out other account sessions');json_response(['ok'=>true]);}
 if(preg_match('~^/api/sessions/([a-f0-9]{64})$~D',$path,$m)&&$method==='DELETE'){$rows=$s->query('SELECT hash FROM cms_sessions WHERE user_id=?',[$id])->fetchAll();foreach($rows as $r)if(hash_equals(hash('sha256','session-list:'.$r['hash']),$m[1])){$s->query('DELETE FROM cms_sessions WHERE hash=?',[$r['hash']]);if(hash_equals($r['hash'],$u['hash']))session_cookie('',0);json_response(['ok'=>true]);}fail(404,'Session not found.');}
 fail(404,'Security endpoint not found.');
}
function security_backup(array $data):array{foreach($data['kv'] as &$row){if($row['name']==='loginChallenges')$row['value']='[]';if($row['name']==='security'){$all=json_decode($row['value'],true,128,JSON_THROW_ON_ERROR);foreach($all as &$d)unset($d['pending']);unset($d);$row['value']=json_encode($all,JSON_THROW_ON_ERROR);}}unset($row);if(is_file(private_dir().'/mfa.key'))$data['mfaKey']=base64_encode(file_get_contents(private_dir().'/mfa.key'));return $data;}
function security_restore_validate(array $metadata,array &$kv):?string{$key=null;if(isset($metadata['mfaKey'])){if(!is_string($metadata['mfaKey']))fail(400,'Backup authenticator key is invalid.');$key=base64_decode($metadata['mfaKey'],true);if($key===false||strlen($key)!==32)fail(400,'Backup authenticator key is invalid.');}$ids=array_column($metadata['users'],'id');$all=$kv['security']??[];if(!is_array($all)||count($all)>100)fail(400,'Backup account security data is invalid.');foreach($all as $id=>&$d){if(!in_array($id,$ids,true)){unset($all[$id]);continue;}if(!is_array($d))fail(400,'Invalid account security record.');unset($d['pending']);if(!empty($d['enabled'])){if($key===null)fail(400,'Backup is missing its authenticator encryption key.');try{$raw=open_secret($d['secret']??'',$key);base32_decode($raw);}catch(Throwable){fail(400,'Backup authenticator data cannot be verified.');}if(!is_array($d['backupHashes']??null)||count($d['backupHashes'])>10)fail(400,'Invalid MFA recovery data.');foreach($d['backupHashes'] as $hash)if(!is_string($hash)||!preg_match('/^[a-f0-9]{64}$/D',$hash))fail(400,'Invalid MFA recovery code hash.');$d['lastStep']=(int)($d['lastStep']??-1);}}unset($d);$kv['security']=$all;$kv['loginChallenges']=[];return $key;}
